def max_sessions(intervals, gap):
    if not intervals:
        return 0
    intervals = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_end = float('-inf')
    for start, end in intervals:
        if start >= last_end + gap:
            count += 1
            last_end = end
    return count

def longest_spaced_repeat(s, gap):
    n = len(s)
    max_L = 0
    for d in range(gap + 1, n):
        # d = q - p; need d - gap >= 1 for L >= 1
        limit = d - gap
        # compute LCPs for all pairs with difference d, from the right
        lcp = 0
        for i in range(n - d - 1, -1, -1):
            if s[i] == s[i + d]:
                lcp += 1
            else:
                lcp = 0
            # lcp is now the match length starting at i (and i+d)
            # it is already <= n - (i + d)
            possible = min(lcp, limit)
            if possible > max_L:
                max_L = possible
    return max_L

def best_circular_selection(values, k):
    if k == 0:
        return 0
    n = len(values)
    if n == 1:
        return values[0]

    def linear_max(arr, kk):
        m = len(arr)
        if kk == 0:
            return 0
        if m == 0 or kk > (m + 1) // 2:
            return None
        NEG = -10**18
        dp_prev2 = [NEG] * (kk + 1)
        dp_prev2[0] = 0
        dp_prev = [NEG] * (kk + 1)
        dp_prev[0] = 0
        if kk >= 1:
            dp_prev[1] = arr[0]
        for i in range(2, m + 1):
            dp_curr = [NEG] * (kk + 1)
            dp_curr[0] = 0
            for j in range(1, kk + 1):
                dp_curr[j] = dp_prev[j]
                if dp_prev2[j - 1] != NEG:
                    candidate = dp_prev2[j - 1] + arr[i - 1]
                    if candidate > dp_curr[j]:
                        dp_curr[j] = candidate
            dp_prev2 = dp_prev
            dp_prev = dp_curr
        res = dp_prev[kk]
        return res if res != NEG else None

    max1 = linear_max(values[1:], k)
    max2 = linear_max(values[:-1], k)
    candidates = [x for x in (max1, max2) if x is not None]
    if not candidates:
        raise ValueError
    return max(candidates)

