def min_cost_route(n, edges, s, t, switch_cost):
    if s == t:
        return 0

    # Map colors to integer ids for efficiency
    color_to_id = {}
    for *_, color in edges:
        if color not in color_to_id:
            color_to_id[color] = len(color_to_id)

    # Adjacency: adj[v][cid] = list of (neighbor, weight)
    adj = [defaultdict(list) for _ in range(n)]
    for u, v, w, color in edges:
        cid = color_to_id[color]
        adj[u][cid].append((v, w))
        if u != v:
            adj[v][cid].append((u, w))

    # Dijkstra states: (node, c) where c >= 0 is color id on arrival,
    # c == -1 denotes the "switch" auxiliary state at the node.
    dist = {}
    pq = []  # (cost, node, c)

    # Initialize with first edges out of s (no switch cost)
    for cid, elist in adj[s].items():
        for nei, w in elist:
            key = (nei, cid)
            if w < dist.get(key, float('inf')):
                dist[key] = w
                heapq.heappush(pq, (w, nei, cid))

    while pq:
        cost, v, c = heapq.heappop(pq)
        key = (v, c)
        if cost > dist.get(key, float('inf')):
            continue

        # First time a colored state at t is settled => global minimum
        if v == t and c >= 0:
            return cost

        if c >= 0:
            # Colored arrival (v, c)
            # Transition to switch state at v
            sw_key = (v, -1)
            new_cost = cost + switch_cost
            if new_cost < dist.get(sw_key, float('inf')):
                dist[sw_key] = new_cost
                heapq.heappush(pq, (new_cost, v, -1))

            # Continue with same color
            for nei, w in adj[v][c]:
                new_cost = cost + w
                nkey = (nei, c)
                if new_cost < dist.get(nkey, float('inf')):
                    dist[nkey] = new_cost
                    heapq.heappush(pq, (new_cost, nei, c))
        else:
            # Switch state (v, -1): take any outgoing edge
            for cid, elist in adj[v].items():
                for nei, w in elist:
                    new_cost = cost + w
                    nkey = (nei, cid)
                    if new_cost < dist.get(nkey, float('inf')):
                        dist[nkey] = new_cost
                        heapq.heappush(pq, (new_cost, nei, cid))

    return -1

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def smallest_balanced(s: str) -> str:
    n = len(s)
    if n % 2 != 0:
        raise ValueError
    open_needed = n // 2
    fixed_open = s.count('(')
    q = s.count('?')
    if fixed_open > open_needed or fixed_open + q < open_needed:
        raise ValueError

    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + (1 if s[i] == '(' else 0)

    res = []
    bal = 0
    for i in range(n):
        if s[i] == '(':
            put = '('
        elif s[i] == ')':
            put = ')'
        else:
            later_must = suffix[i + 1]
            if open_needed > later_must:
                put = '('
            else:
                put = ')'

        if put == '(':
            open_needed -= 1
            bal += 1
        else:
            bal -= 1
        if bal < 0:
            raise ValueError
        res.append(put)

    if open_needed != 0 or bal != 0:
        raise ValueError
    return ''.join(res)

