def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(sr, sc):
        dist = [[math.inf] * C for _ in range(R)]
        dist[sr][sc] = 0
        q = collections.deque([(sr, sc)])
        while q:
            r, col = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, col + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != -1 and dist[nr][nc] == math.inf:
                    dist[nr][nc] = dist[r][col] + 1
                    q.append((nr, nc))
        return dist

    distS = bfs(0, 0)
    distE = bfs(R - 1, C - 1)
    pure = distS[R - 1][C - 1]

    groups = defaultdict(list)
    for r in range(R):
        for col in range(C):
            if grid[r][col] != -1:
                groups[grid[r][col]].append((r, col))

    min_tele = math.inf
    for cells in groups.values():
        if len(cells) < 2:
            continue
        ms = math.inf
        As = None
        me = math.inf
        Be = None
        for pos in cells:
            r, col = pos
            s = distS[r][col]
            e = distE[r][col]
            if s < ms:
                ms = s
                As = pos
            if e < me:
                me = e
                Be = pos
        min_e_neq = math.inf
        min_s_neq = math.inf
        for pos in cells:
            r, col = pos
            if pos != As:
                min_e_neq = min(min_e_neq, distE[r][col])
            if pos != Be:
                min_s_neq = min(min_s_neq, distS[r][col])
        cand = min(ms + min_e_neq, me + min_s_neq)
        if cand < math.inf:
            min_tele = min(min_tele, cand + c)

    result = min(pure, min_tele)
    return result if result < math.inf else -1

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            if d not in graph[pkg]:
                graph[pkg].append(d)
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str) or not amount:
            raise ValueError("invalid amount")
        if "." in amount:
            parts = amount.split(".")
            if len(parts) != 2:
                raise ValueError("invalid amount")
            whole, frac = parts
            if not whole.isdigit() or not frac.isdigit() or not (1 <= len(frac) <= 2):
                raise ValueError("invalid amount")
            cents = int(whole) * 100 + int(frac) * (10 if len(frac) == 1 else 1)
        else:
            if not amount.isdigit():
                raise ValueError("invalid amount")
            cents = int(amount) * 100
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

class UndoStack:
    def __init__(self):
        self._stack = []
        self._history = []  # list of ('push', value) or ('pop', value)

    def push(self, x) -> None:
        self._stack.append(x)
        self._history.append(('push', x))

    def pop(self):
        if not self._stack:
            raise IndexError("pop from empty UndoStack")
        val = self._stack.pop()
        self._history.append(('pop', val))
        return val

    def peek(self):
        if not self._stack:
            raise IndexError("peek from empty UndoStack")
        return self._stack[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, val = self._history.pop()
        if op == 'push':
            self._stack.pop()
        else:  # 'pop'
            self._stack.append(val)

    def __len__(self) -> int:
        return len(self._stack)

class CountingBag:
    def __init__(self):
        self._counts = {}      # item -> current count (>= 1 while present)
        self._entry = {}       # item -> entry moment (when it last went from 0 to 1)
        self._moment = 0       # monotonically increasing entry counter
        self._total = 0        # sum of all counts

    def add(self, item) -> int:
        if self._counts.get(item, 0) == 0:
            # item is entering (or re-entering) the bag
            self._moment += 1
            self._entry[item] = self._moment
            self._counts[item] = 1
        else:
            self._counts[item] += 1
        self._total += 1
        return self._counts[item]

    def discard(self, item) -> bool:
        cnt = self._counts.get(item, 0)
        if cnt == 0:
            return False
        cnt -= 1
        self._total -= 1
        if cnt == 0:
            # item leaves the bag completely
            del self._counts[item]
            del self._entry[item]
        else:
            self._counts[item] = cnt
        return True

    def count(self, item) -> int:
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        return self._total

    def distinct(self) -> int:
        return len(self._counts)

    def most_common(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        # sort by count descending, then by earlier entry moment
        ordered = sorted(
            self._counts.items(),
            key=lambda pair: (-pair[1], self._entry[pair[0]]),
        )
        return ordered[:k]

from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self.capacity = capacity
        self._cache = OrderedDict()  # key -> (value, stored_time, ttl)
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        dead = [
            key
            for key, (_, t, ttl) in self._cache.items()
            if ttl is not None and now >= t + ttl
        ]
        for key in dead:
            del self._cache[key]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive when provided")
        self._purge(now)
        if key in self._cache:
            self._cache[key] = (value, now, ttl)
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self.capacity:
                self._cache.popitem(last=False)
                self._evictions += 1
            self._cache[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._cache:
            self._hits += 1
            self._cache.move_to_end(key)
            return self._cache[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._cache)

class VersionedKV:
    """Key-value store with commit snapshots, point-in-time reads, and rollback."""

    def __init__(self):
        self._working = {}
        # Append-only list of immutable snapshots; index i is version i+1.
        self._history = []

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        # Shallow copy: store mutations (set/delete) must not affect past snapshots.
        self._history.append(dict(self._working))
        return len(self._history)

    def get_at(self, key, version):
        latest = self.latest()
        if not (1 <= version <= latest):
            raise ValueError(
                f"version must be in [1, {latest}], got {version}"
            )
        snapshot = self._history[version - 1]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version) -> None:
        latest = self.latest()
        if not (0 <= version <= latest):
            raise ValueError(
                f"version must be in [0, {latest}], got {version}"
            )
        if version == 0:
            self._working = {}
        else:
            self._working = dict(self._history[version - 1])

    def latest(self) -> int:
        return len(self._history)

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        if ordered[i][0] == prev[0] or ordered[i][0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    n = len(lines)
    for start, delete, insert in ordered:
        if start < 0 or start + delete > n:
            raise ValueError("hunk out of range")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

import bisect

class IntervalSet:
    def __init__(self):
        self._intervals = []  # sorted list of disjoint, non-adjacent (lo, hi) with lo < hi

    def add(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be < hi")
        new_intervals = []
        i = 0
        n = len(self._intervals)
        # Keep intervals that end strictly before lo (no touch/overlap)
        while i < n and self._intervals[i][1] < lo:
            new_intervals.append(self._intervals[i])
            i += 1
        # Merge all intervals that overlap or touch [lo, hi)
        while i < n and self._intervals[i][0] <= hi:
            lo = min(lo, self._intervals[i][0])
            hi = max(hi, self._intervals[i][1])
            i += 1
        new_intervals.append((lo, hi))
        # Append the remaining intervals
        while i < n:
            new_intervals.append(self._intervals[i])
            i += 1
        self._intervals = new_intervals

    def remove(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be < hi")
        new_intervals = []
        for a, b in self._intervals:
            if b <= lo or a >= hi:
                # No overlap with [lo, hi)
                new_intervals.append((a, b))
            else:
                # Overlap: keep any left remnant and/or right remnant
                if a < lo:
                    new_intervals.append((a, lo))
                if b > hi:
                    new_intervals.append((hi, b))
        self._intervals = new_intervals

    def contains(self, x):
        # Find the rightmost interval whose lo <= x
        i = bisect.bisect_right(self._intervals, (x, float('inf'))) - 1
        if i >= 0:
            a, b = self._intervals[i]
            return a <= x < b
        return False

    def total(self):
        return sum(hi - lo for lo, hi in self._intervals)

    def intervals(self):
        return list(self._intervals)

    def gaps(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be < hi")
        result = []
        current = lo
        for a, b in self._intervals:
            if b <= lo:
                continue
            if a >= hi:
                break
            # [a, b) overlaps the window
            if a > current:
                gap_hi = min(a, hi)
                if current < gap_hi:
                    result.append((current, gap_hi))
            current = max(current, b)
            if current >= hi:
                break
        if current < hi:
            result.append((current, hi))
        return result

class Leaderboard:
    def __init__(self):
        self._bests = {}
        self._times = {}
        self._clock = 0

    def submit(self, player, score):
        if player not in self._bests or score > self._bests[player]:
            self._bests[player] = score
            self._times[player] = self._clock
            self._clock += 1
            return True
        return False

    def best(self, player):
        if player not in self._bests:
            raise KeyError(player)
        return self._bests[player]

    def rank(self, player):
        if player not in self._bests:
            raise KeyError(player)
        my = self._bests[player]
        return 1 + sum(1 for s in self._bests.values() if s > my)

    def top(self, k):
        if k < 0:
            raise ValueError
        if k == 0:
            return []
        ordered = sorted(
            self._bests,
            key=lambda p: (-self._bests[p], self._times[p]),
        )
        return [(p, self._bests[p]) for p in ordered[:k]]

    def player_count(self):
        return len(self._bests)

import heapq

class TaskScheduler:
    def __init__(self):
        self._heap = []  # entries: (-priority, submit_time, task_id)
        self._time = 0
        self._active = {}  # task_id -> (priority, submit_time)

    def submit(self, task_id, priority):
        if task_id in self._active:
            raise ValueError("task already active")
        self._time += 1
        t = self._time
        self._active[task_id] = (priority, t)
        heapq.heappush(self._heap, (-priority, t, task_id))

    def reprioritize(self, task_id, priority):
        if task_id not in self._active:
            raise KeyError(task_id)
        _, t = self._active[task_id]
        self._active[task_id] = (priority, t)
        heapq.heappush(self._heap, (-priority, t, task_id))

    def cancel(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        del self._active[task_id]

    def _clean(self):
        while self._heap:
            neg_p, t, tid = self._heap[0]
            if tid in self._active and self._active[tid] == (-neg_p, t):
                break
            heapq.heappop(self._heap)

    def pop(self):
        self._clean()
        if not self._heap:
            raise IndexError("pop from empty scheduler")
        _, _, tid = heapq.heappop(self._heap)
        del self._active[tid]
        return tid

    def peek(self):
        self._clean()
        if not self._heap:
            raise IndexError("peek from empty scheduler")
        return self._heap[0][2]

    def priority_of(self, task_id):
        if task_id not in self._active:
            raise KeyError(task_id)
        return self._active[task_id][0]

    def __len__(self):
        return len(self._active)

def rank_scores(scores: list) -> list[int]:
    if any(x != x for x in scores):
        raise ValueError("NaN scores are not allowed")
    return [1 + sum(1 for s in scores if s > score) for score in scores]

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W <= 0:
        raise ValueError("total weight must be positive")
    pairs = sorted(zip(values, weights), key=lambda p: p[0])
    threshold = W / 2 - 1e-9
    cum = 0.0
    for v, w in pairs:
        cum += w
        if cum >= threshold:
            return v
    return pairs[-1][0]

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be >= 0")

    def is_combining(ch: str) -> bool:
        return unicodedata.category(ch) in ("Mn", "Mc", "Me")

    if not s or width == 0:
        return ""

    units = []
    i = 0
    n = len(s)
    while i < n:
        start = i
        i += 1
        while i < n and is_combining(s[i]):
            i += 1
        units.append(s[start:i])

    return "".join(units[:width])

import math

def vector_norm(v: list[float]) -> float:
    if not v:
        return 0.0
    for x in v:
        if not math.isfinite(x):
            raise ValueError("vector entries must be finite")
    max_abs = 0.0
    for x in v:
        ax = abs(x)
        if ax > max_abs:
            max_abs = ax
    if max_abs == 0.0:
        return 0.0
    sum_sq = 0.0
    for x in v:
        sum_sq += (x / max_abs) ** 2
    return max_abs * math.sqrt(sum_sq)

def round_robin(iterables: list):
    """Lazily interleave values from *iterables* in round-robin order.

    Exhausted iterables drop out; remaining ones keep their relative order.
    Inputs are advanced only as far as needed for the values requested so far.
    """
    iterators = [iter(it) for it in iterables]
    while iterators:
        next_round = []
        for it in iterators:
            try:
                yield next(it)
                next_round.append(it)
            except StopIteration:
                pass
        iterators = next_round

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError("n must be nonnegative and k must be a positive integer")
    if n <= 1 or k == 1:
        return n

    def pow_leq(base: int, exp: int, limit: int) -> bool:
        """Return True iff base**exp <= limit, without constructing integers larger than limit."""
        if base == 0:
            return True  # 0**exp == 0 for exp >= 1
        result = 1
        while exp > 0:
            if exp & 1:
                if result > limit // base:
                    return False
                result *= base
            exp >>= 1
            if exp == 0:
                break
            if base > limit // base:
                return False
            base *= base
        return True

    # For n >= 2, if k is at least the bit length then 2**k > n, so the answer is 1.
    if k >= n.bit_length():
        return 1

    low = 1
    high = n
    while low < high:
        mid = (low + high + 1) // 2
        if pow_leq(mid, k, n):
            low = mid
        else:
            high = mid - 1
    return low

def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError
    even = [0] * m
    odd = [0] * m
    for v in values:
        r = v % m
        if v % 2 == 0:
            even[r] += 1
        else:
            odd[r] += 1

    def count_pairs(cnt: list[int]) -> int:
        total = 0
        for r in range(m):
            s = (m - r) % m
            if r < s:
                total += cnt[r] * cnt[s]
            elif r == s:
                c = cnt[r]
                total += c * (c - 1) // 2
        return total

    return count_pairs(even) + count_pairs(odd)

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    events = []
    for s, e in intervals:
        events.append((s, 1))
        events.append((e, -1))
    events.sort()  # sorts by time ascending, then by delta (-1 before +1)
    current = 0
    max_load = 0
    earliest = 0
    i = 0
    n = len(events)
    while i < n:
        t = events[i][0]
        while i < n and events[i][0] == t:
            current += events[i][1]
            i += 1
        if current > max_load:
            max_load = current
            earliest = t
    return (max_load, earliest)

class MergeLedger:
    def __init__(self):
        self.parent = {}
        self.value = {}
        self.size = {}
        self.csum = {}
        self.members = {}
        self.history = []
        self.num_components = 0

    def add(self, x, value=0):
        if x in self.parent:
            raise ValueError(x)
        self.parent[x] = x
        self.value[x] = value
        self.size[x] = 1
        self.csum[x] = value
        self.members[x] = [x]
        self.num_components += 1

    def find(self, x):
        if x not in self.parent:
            raise KeyError(x)
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def merge(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        # attach rb to ra
        self.parent[rb] = ra
        self.members[ra].extend(self.members[rb])
        self.size[ra] += self.size[rb]
        self.csum[ra] += self.csum[rb]
        self.history.append((rb, ra))
        self.num_components -= 1
        return True

    def same(self, a, b):
        return self.find(a) == self.find(b)

    def component_size(self, x):
        return self.size[self.find(x)]

    def component_value(self, x):
        return self.csum[self.find(x)]

    def add_value(self, x, delta):
        r = self.find(x)
        self.value[x] += delta
        self.csum[r] += delta

    def components(self):
        return self.num_components

    def undo(self):
        if not self.history:
            raise RuntimeError("no merge to undo")
        small, large = self.history.pop()
        self.parent[small] = small
        small_size = self.size[small]
        del self.members[large][-small_size:]
        self.size[large] -= small_size
        small_sum = sum(self.value[e] for e in self.members[small])
        self.csum[large] -= small_sum
        self.csum[small] = small_sum
        self.num_components += 1

from bisect import bisect_right

def count_dominant_pairs(seq: list[int]) -> int:
    n = len(seq)
    if n < 2:
        return 0

    unique = sorted(set(seq))
    m = len(unique)
    rank = {v: i + 1 for i, v in enumerate(unique)}

    class Fenwick:
        def __init__(self, size: int):
            self.n = size
            self.tree = [0] * (size + 1)

        def update(self, i: int, delta: int = 1) -> None:
            while i <= self.n:
                self.tree[i] += delta
                i += i & -i

        def query(self, i: int) -> int:
            s = 0
            while i > 0:
                s += self.tree[i]
                i -= i & -i
            return s

    ft = Fenwick(m)
    ans = 0
    for i in range(n - 1, -1, -1):
        y = seq[i]
        thresh = (y - 1) // 3
        j = bisect_right(unique, thresh)
        if j > 0:
            ans += ft.query(j)
        ft.update(rank[y])
    return ans

def longest_echo(s: str) -> int:
    n = len(s)
    if n <= 1:
        return 0

    def has_repeat(L: int) -> bool:
        if L == 0:
            return True
        base1, mod1 = 911382323, 10**9 + 7
        base2, mod2 = 972663749, 10**9 + 9
        h1 = h2 = 0
        p1 = p2 = 1
        for i in range(L):
            h1 = (h1 * base1 + ord(s[i])) % mod1
            h2 = (h2 * base2 + ord(s[i])) % mod2
            if i < L - 1:
                p1 = (p1 * base1) % mod1
                p2 = (p2 * base2) % mod2
        pos = {}
        key = (h1, h2)
        pos[key] = [0]
        for i in range(1, n - L + 1):
            h1 = (h1 - ord(s[i - 1]) * p1) % mod1
            h1 = (h1 * base1 + ord(s[i + L - 1])) % mod1
            h2 = (h2 - ord(s[i - 1]) * p2) % mod2
            h2 = (h2 * base2 + ord(s[i + L - 1])) % mod2
            key = (h1, h2)
            for j in pos.get(key, []):
                if all(s[j + k] == s[i + k] for k in range(L)):
                    return True
            if key not in pos:
                pos[key] = []
            pos[key].append(i)
        return False

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if has_repeat(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

import heapq

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be >= 1")
    if not jobs:
        return 0
    jobs = sorted(jobs, key=lambda job: job[0])
    heap: list[int] = []
    total = 0
    for d, p in jobs:
        heapq.heappush(heap, p)
        total += p
        capacity = d * cap
        while len(heap) > capacity:
            total -= heapq.heappop(heap)
    return total

def min_insertions(s, allowed):
    n = len(s)
    if n <= 1:
        return 0
    allowed_set = set(allowed)
    INF = float('inf')
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            cand = INF
            if s[i] == s[j]:
                mid = 0 if length == 2 else dp[i + 1][j - 1]
                cand = min(cand, mid)
            if s[i] in allowed_set:
                cand = min(cand, 1 + dp[i + 1][j])
            if s[j] in allowed_set:
                cand = min(cand, 1 + dp[i][j - 1])
            dp[i][j] = cand
    res = dp[0][n - 1]
    return -1 if res == INF else res

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if (isinstance(low, bool) or isinstance(high, bool) or
            not isinstance(low, (int, float)) or not isinstance(high, (int, float))):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    result = []
    for i, x in enumerate(values):
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            raise TypeError(f"index {i}")
        if x < low:
            result.append(low)
        elif x > high:
            result.append(high)
        else:
            result.append(x)
    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if not text.strip():
        raise ValueError("empty duration")
    multipliers = {'h': 3600, 'm': 60, 's': 1}
    order = 'hms'
    pos = 0
    total = 0
    i = 0
    n = len(text)
    while i < n:
        if not text[i].isdigit():
            raise ValueError("malformed duration")
        j = i
        while j < n and text[j].isdigit():
            j += 1
        if j == n or text[j] not in multipliers:
            raise ValueError("malformed duration")
        unit = text[j]
        unit_pos = order.find(unit)
        if unit_pos < pos:
            raise ValueError("malformed duration")
        pos = unit_pos + 1
        num = int(text[i:j])
        total += num * multipliers[unit]
        i = j + 1
    return total

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    result = []
    stack = [(iter(nested), max_depth)]
    while stack:
        iterator, depth = stack[-1]
        try:
            item = next(iterator)
            if isinstance(item, list) and depth > 0:
                stack.append((iter(item), depth - 1))
            else:
                result.append(item)
        except StopIteration:
            stack.pop()
    return result

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")
    if k == 0:
        return []

    counts = {}
    order = []
    for item in items:
        if item not in counts:
            counts[item] = 0
            order.append(item)
        counts[item] += 1

    n = len(order)
    if k > n:
        k = n

    result = []
    used = set()
    for _ in range(k):
        best_val = None
        best_count = -1
        best_pos = None
        for i, val in enumerate(order):
            if val in used:
                continue
            cnt = counts[val]
            if best_val is None or cnt > best_count or (cnt == best_count and i < best_pos):
                best_val = val
                best_count = cnt
                best_pos = i
        result.append((best_val, best_count))
        used.add(best_val)
    return result

def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError("lo and hi must satisfy 1 <= lo <= hi <= len(deltas)")

    prefix_mod = [0] * (n + 1)
    curr = 0
    for i in range(n):
        curr += deltas[i]
        prefix_mod[i + 1] = curr % k

    freq = {}
    ans = 0
    left_ptr = 0
    right_ptr = -1

    for r in range(1, n + 1):
        target_left = max(0, r - hi)
        target_right = r - lo

        if target_right >= 0:
            while right_ptr < target_right:
                right_ptr += 1
                m = prefix_mod[right_ptr]
                freq[m] = freq.get(m, 0) + 1

        while left_ptr <= right_ptr and left_ptr < target_left:
            m = prefix_mod[left_ptr]
            freq[m] -= 1
            if freq[m] == 0:
                del freq[m]
            left_ptr += 1

        ans += freq.get(prefix_mod[r], 0)

    return ans

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    result = {}
    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i}")
        category, amount, refunded = row
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}")
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}")
        if amount < 0:
            raise ValueError(f"row {i}")
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}")
        if category not in result:
            result[category] = {
                "count": 0,
                "gross": 0.0,
                "net": 0.0,
                "largest": 0.0,
            }
        summary = result[category]
        summary["count"] += 1
        amt = float(amount)
        summary["gross"] += amt
        if not refunded:
            summary["net"] += amt
        if amt > summary["largest"]:
            summary["largest"] = amt
    return result

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    result = []
    i = 0
    n = len(template)

    while i < n:
        c = template[i]
        if c == '{':
            if i + 1 < n and template[i + 1] == '{':
                result.append('{')
                i += 2
            else:
                start = i
                i += 1
                name_chars = []
                while i < n and template[i] != '}':
                    ch = template[i]
                    if not (
                        ('A' <= ch <= 'Z')
                        or ('a' <= ch <= 'z')
                        or ('0' <= ch <= '9')
                        or ch == '_'
                    ):
                        raise ValueError(
                            "invalid placeholder at position " + str(start)
                        )
                    name_chars.append(ch)
                    i += 1
                if i >= n:
                    raise ValueError(
                        "unclosed placeholder at position " + str(start)
                    )
                if not name_chars:
                    raise ValueError(
                        "empty placeholder at position " + str(start)
                    )
                name = ''.join(name_chars)
                if name not in context:
                    raise KeyError(name)
                result.append(str(context[name]))
                i += 1
        elif c == '}':
            if i + 1 < n and template[i + 1] == '}':
                result.append('}')
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            result.append(c)
            i += 1

    return ''.join(result)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if tokens == []:
        raise ValueError("empty expression")

    stack = []

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError("token {0}".format(i))

        if token == "+" or token == "-" or token == "*" or token == "/":
            if len(stack) < 2:
                raise ValueError("stack underflow at token {0}".format(i))
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError("token {0}".format(i))
                if (left < 0) != (right < 0):
                    stack.append(-(abs(left) // abs(right)))
                else:
                    stack.append(abs(left) // abs(right))
        else:
            valid = True
            n = len(token)
            if n == 0:
                valid = False
            else:
                pos = 0
                if token[0] == "+" or token[0] == "-":
                    pos = 1
                if pos >= n:
                    valid = False
                else:
                    j = pos
                    while j < n:
                        c = token[j]
                        if c < "0" or c > "9":
                            valid = False
                            break
                        j += 1
            if not valid:
                raise ValueError("unknown token at token {0}".format(i))
            stack.append(int(token))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")
    segments = path.split(".")
    if "" in segments:
        raise ValueError("empty segment")

    def recurse(node, segs):
        if not segs:
            return node
        seg = segs[0]
        rest = segs[1:]
        if isinstance(node, dict):
            if seg not in node:
                raise KeyError(seg)
            return recurse(node[seg], rest)
        if isinstance(node, list):
            if seg.startswith("-"):
                digits = seg[1:]
            else:
                digits = seg
            if not digits or not digits.isdigit():
                raise ValueError("invalid index")
            idx = int(seg)
            length = len(node)
            if idx < -length or idx >= length:
                raise IndexError(seg)
            return recurse(node[idx], rest)
        raise TypeError("cannot descend")

    return recurse(data, segments)
